import com.example.starter.transfer.TransferDtos.VerifyRequest;
import com.example.starter.transfer.TransferDtos.VerifyResponse;

/**
 * 转关主流程业务测试：申请幂等、核注扣减原子性、48 小时边界、分批核销、
 * 核销不超余量、撤销、结案终态、异常解除与状态留痕。
