        VerifyResponse second = service.verify(order.orderId(), new VerifyRequest("V-30b",
                List.of(new VerifyItemRequest(TARIFF_A, 4), new VerifyItemRequest(TARIFF_B, 4))));
        assertTrue(second.closed());
