        service.endorse(order.orderId());
        service.verify(order.orderId(),
                new VerifyRequest("V-31a", List.of(new VerifyItemRequest(TARIFF_A, 6))));

        // 同批中 TARIFF_B 超量（余量 4 请求 5），整批拒绝：TARIFF_A 的 4 也不生效
